const Components = () => {
  const [selectedComponent, setSelectedComponent] = useState(() => {
    const savedComponentName = localStorage.getItem('selectedComponentName');
    return components.find(comp => comp.name === savedComponentName) || components[0];
  });
  const navigate = useNavigate();

  useEffect(() => {
    localStorage.setItem('selectedComponentName', selectedComponent.name);
  }, [selectedComponent]);

  const [isFullScreen, setIsFullScreen] = useState(false);

  const handleCodeClick = (componentName) => {
    // Check if showcode.jsx exists for the component
    const hasShowCode = componentName === "ThreeDCardDemo"; // Currently only ThreeDCard has showcode.jsx

    if (hasShowCode) {
      navigate(`/code/${componentName}`);
    } else {
      // Show a modal or alert for "Updating Soon"
      alert("Code documentation is being updated. Coming soon!");
    }
  };

  return (
    <div className="mt-16 fixed inset-0 flex bg-gradient-to-b from-gray-700 to-black text-white overflow-hidden">
      {/* Fixed Left Sidebar - No Scroll */}
      <div className="w-1/4 bg-gradient-to-b from-gray-700 to-black p-3">
        <h2 className="text-gray-300 mb-4 font-semibold text-lg">All Components</h2>
        <ul>
          {components.map((comp, index) => (
            <li 
              key={index} 
              className={`text-gray-400 mb-2 cursor-pointer hover:text-white transition-colors duration-300 ${
                selectedComponent.name === comp.name ? 'font-bold' : ''
              }`} 
              onClick={() => setSelectedComponent(comp)}
            >
              {comp.name}
            </li>
          ))}
        </ul>
      </div>

      {/* Scrollable Right Content */}
      <div className="w-3/4 p-4 overflow-y-auto">
        <h2 className="text-3xl font-bold mb-2">{selectedComponent.name}</h2>
        <p className="text-gray-400 mb-4">{selectedComponent.description}</p>
        <div className="flex space-x-4 mb-4">
          <button 
            className="bg-gray-800 text-white py-2 px-6 rounded-lg hover:bg-gray-700 flex items-center space-x-2 h-10" 
            onClick={() => setIsFullScreen(true)}
          >
            <FaEye className="text-lg"/>
            <span>Preview</span>
          </button>
          <button 
            className="bg-gray-800 text-white py-2 px-6 rounded-lg hover:bg-gray-700 flex items-center space-x-2 h-10"
            onClick={() => handleCodeClick(selectedComponent.name)}
          >
            <FaCode className="text-lg"/>
            <span>Code</span>
          </button>
        </div>
        <div className="bg-gray-900 p-6 rounded-lg shadow-lg flex justify-center items-center">
          {selectedComponent.demo}
        </div>
      </div>

      {isFullScreen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50">
          <div className="w-full h-full p-4">
            <div className="relative w-full h-full">
              <button
                onClick={() => setIsFullScreen(false)}
                className="absolute top-4 right-4 text-white hover:text-gray-300"
              >
                Close
              </button>
              <div className="w-full h-full flex items-center justify-center">
                {selectedComponent.demo}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

