"use client";

import React, { useState } from 'react';
import { FaCopy, FaCheck, FaArrowLeft } from 'react-icons/fa';
import { motion } from 'framer-motion';
import { useParams, useNavigate } from 'react-router-dom';

export function ShowCodeDemo() {
  const { componentName } = useParams();
  const navigate = useNavigate();
  const [copiedSection, setCopiedSection] = useState('');

  const components = {
    CLI: {
      title: "Install dependencies",
      code: `npm i motion clsx tailwind-merge`
    },
    Manual: {
      title: "lib/utils.ts",
      code: `import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}`
    },
    Component: {
      title: "components/ui/3d-card.tsx",
      code: `"use client";

import { cn } from "@/lib/utils";
import { createContext, useContext, useRef, useState } from "react";

const MouseEnterContext = createContext<
  [boolean, React.Dispatch<React.SetStateAction<boolean>>] | undefined
>(undefined);

export const CardContainer = ({
  children,
  className,
  containerClassName,
}: {
  children?: React.ReactNode;
  className?: string;
  containerClassName?: string;
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMouseEntered, setIsMouseEntered] = useState(false);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const { left, top, width, height } =
      containerRef.current.getBoundingClientRect();
    const x = (e.clientX - left) / width;
    const y = (e.clientY - top) / height;
    const multiplier = 20;
    const xOffset = -(y - 0.5) * multiplier;
    const yOffset = (x - 0.5) * multiplier;
    
    containerRef.current.style.transform =
      isMouseEntered ? \`perspective(1000px) rotateX(\${xOffset}deg) rotateY(\${yOffset}deg)\` : "none";
  };

  return (
    <MouseEnterContext.Provider value={[isMouseEntered, setIsMouseEntered]}>
      <div
        className={cn("flex items-center justify-center", containerClassName)}
        style={{
          perspective: "1000px",
        }}
      >
        <div
          ref={containerRef}
          onMouseEnter={() => setIsMouseEntered(true)}
          onMouseLeave={() => {
            setIsMouseEntered(false);
            if (containerRef.current)
              containerRef.current.style.transform = "none";
          }}
          onMouseMove={handleMouseMove}
          className={cn("flex items-center justify-center relative", className)}
        >
          {children}
        </div>
      </div>
    </MouseEnterContext.Provider>
  );
};

export const CardBody = ({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) => {
  return (
    <div
      className={cn(
        "h-96 w-96 [transform-style:preserve-3d]  [&>*]:[transform-style:preserve-3d]",
        className
      )}
    >
      {children}
    </div>
  );
};

export const CardItem = ({
  as: Component = "div",
  children,
  className,
  translateX = 0,
  translateY = 0,
  translateZ = 0,
  rotateX = 0,
  rotateY = 0,
  rotateZ = 0,
  ...rest
}: {
  as?: any;
  children: React.ReactNode;
  className?: string;
  translateX?: number | string;
  translateY?: number | string;
  translateZ?: number | string;
  rotateX?: number | string;
  rotateY?: number | string;
  rotateZ?: number | string;
}) => {
  const ref = useRef<HTMLDivElement>(null);
  const [isMouseEntered] = useMouseEnter();

  return (
    <Component
      ref={ref}
      className={cn("", className)}
      style={{
        transform: isMouseEntered
          ? \`translate3d(\${translateX}px, \${translateY}px, \${translateZ}px) rotateX(\${rotateX}deg) rotateY(\${rotateY}deg) rotateZ(\${rotateZ}deg)\`
          : "none",
        transition: "transform 200ms",
      }}
      {...rest}
    >
      {children}
    </Component>
  );
};

export const useMouseEnter = () => {
  const context = useContext(MouseEnterContext);
  if (context === undefined) {
    throw new Error("useMouseEnter must be used within a MouseEnterContext");
  }
  return context;
};`
    }
  };

  const handleCopy = (section) => {
    navigator.clipboard.writeText(components[section].code);
    setCopiedSection(section);
    setTimeout(() => setCopiedSection(''), 2000);
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 p-8">
      <div className="max-w-4xl mx-auto">
        {/* Back Button */}
        <button
          onClick={() => navigate('/components')}
          className="flex items-center space-x-2 text-gray-400 hover:text-white mb-6"
        >
          <FaArrowLeft />
          <span>Back to Components</span>
        </button>

        <h2 className="text-2xl font-bold mb-4">Installation</h2>
        
        {/* All Sections in Column */}
        <div className="space-y-8">
          {Object.entries(components).map(([section, { title, code }]) => (
            <div key={section} className="space-y-2">
              <h3 className="text-lg text-gray-400">{title}</h3>
              <div className="relative">
                <pre className="bg-gray-900 p-4 rounded-lg overflow-x-auto">
                  <code className="text-sm font-mono text-gray-300">
                    {code}
                  </code>
                </pre>
                
                {/* Copy Button */}
                <button
                  onClick={() => handleCopy(section)}
                  className="absolute top-4 right-4 p-2 rounded-lg bg-gray-800 hover:bg-gray-700 text-gray-400 hover:text-white"
                >
                  {copiedSection === section ? (
                    <motion.div
                      initial={{ scale: 0 }}
                      animate={{ scale: 1 }}
                      exit={{ scale: 0 }}
                    >
                      <FaCheck className="text-green-500" />
                    </motion.div>
                  ) : (
                    <FaCopy />
                  )}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}